update public.learning_paths
set
  title = 'Art History I (Ancient to Medieval)',
  goal = 'Art History I (Ancient to Medieval)',
  summary = 'Art History I introduces visual and material culture from prehistory through the medieval period, with sustained attention to method, object study, chronology, religion, empire, ritual, architecture, manuscripts, craft, exchange, museums, and cultural heritage ethics. The course is global in ambition while preserving the Fine Arts survey sequence expected of an ancient-to-medieval art history core.',
  data = $ah1json${"slug": "art-history-i-ancient-to-medieval", "title": "Art History I (Ancient to Medieval)", "description": "Art History I introduces visual and material culture from prehistory through the medieval period, with sustained attention to method, object study, chronology, religion, empire, ritual, architecture, manuscripts, craft, exchange, museums, and cultural heritage ethics. The course is global in ambition while preserving the Fine Arts survey sequence expected of an ancient-to-medieval art history core.", "topics": [{"id": "b55ed838-7982-44ad-9005-52653a38566c", "type": "topic", "title": "Art-Historical Methods, Visual Analysis, and Object Study", "description": "This opening topic teaches students how art historians move from looking to interpretation. It establishes the vocabulary, evidence habits, and ethical care needed for the rest of the survey.", "children": [{"id": "a1e103be-bc3c-41c9-8a44-6e2c63d26218", "type": "subtopic", "title": "Formal analysis", "children": [{"id": "ab0689e2-2003-4e5b-bbe1-26789e49ea56", "type": "concept", "title": "Line, shape, color, texture, scale, and composition"}, {"id": "0e613976-deb2-45d4-b6da-ba7ea7bd0a20", "type": "concept", "title": "Material, technique, style, and condition"}, {"id": "e9b1290d-9fe3-4345-ae69-4743c5043f5a", "type": "concept", "title": "Spatial organization, proportion, and movement"}], "description": "Students learn to describe what they see before explaining what it means."}, {"id": "e80c6f04-87b9-4cb0-8201-a21074adc2ad", "type": "subtopic", "title": "Context and function", "children": [{"id": "64929b11-0cc6-4ab1-abae-c0720894c1e8", "type": "concept", "title": "Patronage, workshop, and audience"}, {"id": "26b06649-3796-4ce2-813c-f3ea027577f6", "type": "concept", "title": "Ritual, political, domestic, and funerary use"}, {"id": "cc7f4906-7989-44a9-9aa1-17d7bce9bdda", "type": "concept", "title": "Original setting versus museum display"}], "description": "Students connect objects to the people, institutions, rituals, and places that shaped them."}, {"id": "38a322e7-fbe9-4229-bac9-382ec0d8c0a5", "type": "subtopic", "title": "Evidence and interpretation", "children": [{"id": "8a2244c9-5dd3-4301-9c82-6aafd279c572", "type": "concept", "title": "Primary sources, inscriptions, and archaeology"}, {"id": "be680e8d-78af-4db1-b6d6-288a6791f22c", "type": "concept", "title": "Comparative objects and chronologies"}, {"id": "3e0b5847-66a2-4bb5-9367-bc305070e03f", "type": "concept", "title": "Provenance, gaps, uncertainty, and debate"}], "description": "Students learn that art-historical claims require evidence, comparison, and awareness of limits."}]}, {"id": "11c0ba0d-ce37-4bf6-9345-e7c81b63352b", "type": "topic", "title": "Prehistoric Art and Ritual Landscapes", "description": "Prehistoric art introduces image-making before written archives. Students learn how art historians and archaeologists interpret objects, bodies, caves, monuments, and landscapes with incomplete evidence.", "children": [{"id": "f1578f3e-b36d-41c1-9dc5-4208a7fdb3de", "type": "subtopic", "title": "Paleolithic image-making", "children": [{"id": "fdd040f5-b59e-49ad-8141-da9abbca05ef", "type": "concept", "title": "Cave painting and engraving"}, {"id": "c6376a4c-ef5e-44c9-bf39-611d52fe8896", "type": "concept", "title": "Portable figurines and small-scale sculpture"}, {"id": "858f04e4-eb97-4356-8093-16a4619740b5", "type": "concept", "title": "Animal imagery, abstraction, and interpretation"}], "description": "Students examine early images as evidence of perception, material skill, ritual, and social life."}, {"id": "8d70c0a3-e5a2-4ab7-8e2a-e96c7e58965e", "type": "subtopic", "title": "Neolithic communities and monuments", "children": [{"id": "b2b910de-fdae-4d69-aa92-79af3df5959c", "type": "concept", "title": "Megaliths and henges"}, {"id": "854ea352-78ed-470c-ba4f-20ebe13678c0", "type": "concept", "title": "Plaster, ceramics, and domestic ritual"}, {"id": "375be63e-6174-4376-9982-fa9d471a47e1", "type": "concept", "title": "Agriculture, social organization, and memory"}], "description": "This subtopic connects settlement, agriculture, ritual, and built landscapes."}, {"id": "47697741-261b-484f-9758-5c8e96d6aefa", "type": "subtopic", "title": "Archaeological method and caution", "children": [{"id": "0cf57963-f3d1-4ead-b0a0-380de32e158a", "type": "concept", "title": "Dating methods and stratigraphy"}, {"id": "85aa778c-13c5-457e-a353-17fa3c43f771", "type": "concept", "title": "Ethnographic analogy and its limits"}, {"id": "a1cce24f-0275-40e5-995b-b2a02c80c7d8", "type": "concept", "title": "Ritual, gender, and social identity debates"}], "description": "Students learn why prehistoric art requires careful distinction between evidence and speculation."}]}, {"id": "ee25f1de-ed5b-4ce9-92f8-fd3dc9f1572c", "type": "topic", "title": "Ancient Near East and Mesopotamia", "description": "The ancient Near East shows how cities, writing, kingship, temples, trade, and empire shaped visual culture. Students learn to read art as social power and sacred order.", "children": [{"id": "da09c4d5-ba8e-4139-9c23-f65a79383e0f", "type": "subtopic", "title": "Cities, temples, and ziggurats", "children": [{"id": "18a490ac-f5b5-4c90-b699-989fe764c2f2", "type": "concept", "title": "Sumerian city-states"}, {"id": "4e61c824-aa01-4121-bdba-9f8fe394469d", "type": "concept", "title": "Ziggurat form and temple precincts"}, {"id": "607ed359-8c0f-4670-893c-fe09cbfc1910", "type": "concept", "title": "Mudbrick, labor, and sacred geography"}], "description": "Students connect architecture to urban life, ritual, and political authority."}, {"id": "ebb4f531-797a-453b-9b52-1abae51c8213", "type": "subtopic", "title": "Kingship, law, and empire", "children": [{"id": "c76bf054-ccaf-4344-a43c-5a35dbb4973b", "type": "concept", "title": "Victory steles and royal reliefs"}, {"id": "1d25e5dc-2238-42e2-96bd-cb07b0d2067c", "type": "concept", "title": "Codes, treaties, and public monuments"}, {"id": "d3111954-9858-46eb-9a86-e1cab48f325f", "type": "concept", "title": "Assyrian palace reliefs and imperial narrative"}], "description": "This subtopic shows how rulers used images and inscriptions to make authority visible."}, {"id": "013a384a-6093-41dd-9799-ef6cad0bdecd", "type": "subtopic", "title": "Materials, trade, and luxury objects", "children": [{"id": "79829762-b164-4190-a358-3c046bce5e6d", "type": "concept", "title": "Cylinder seals and administrative images"}, {"id": "ea60708d-afea-4ed9-b2f6-2ad6dbc73dbf", "type": "concept", "title": "Metalwork, inlay, and lapis lazuli"}, {"id": "2f801c66-54e1-4dc6-b5b6-55e681e2a5d5", "type": "concept", "title": "Objects as evidence of contact and hierarchy"}], "description": "Students examine how scarce materials reveal exchange networks and elite display."}]}, {"id": "1c3f3fb6-9f52-4f0b-8598-eab9bd520fbe", "type": "topic", "title": "Ancient Egypt and Nubia", "description": "Egyptian and Nubian art teach students how image, writing, ritual, kingship, death, and landscape can form a durable visual system over millennia.", "children": [{"id": "dc928e84-c0fd-47cd-afa4-3aae43677c56", "type": "subtopic", "title": "Pharaonic image systems", "children": [{"id": "1adab3ce-644c-465c-aadd-81b16dc75ed2", "type": "concept", "title": "Registers, scale hierarchy, and composite view"}, {"id": "e1aeb3a9-29b1-41b9-b2cb-d986fe9b7f6d", "type": "concept", "title": "Canon of proportions"}, {"id": "8e8e1ec2-ed04-4eac-9d3b-83837436cef3", "type": "concept", "title": "Ma'at, kingship, and divine order"}], "description": "Students learn the visual rules that made status, identity, and cosmic order legible."}, {"id": "9c6bb8a0-4320-4c92-aac7-72c27390dd85", "type": "subtopic", "title": "Tombs, temples, and afterlife", "children": [{"id": "6456572e-05bf-4a33-8905-202d4c296101", "type": "concept", "title": "Mastabas, pyramids, and rock-cut tombs"}, {"id": "87a6e351-1e3e-450f-82d8-d84a60ccc824", "type": "concept", "title": "Mortuary temples and processional routes"}, {"id": "8a616911-1f53-4732-8970-a3bb1018fd8b", "type": "concept", "title": "Mummies, coffins, and Book of the Dead imagery"}], "description": "This subtopic connects architecture, sculpture, painting, and funerary belief."}, {"id": "e73d4d39-f73f-4fad-b637-3b435954da11", "type": "subtopic", "title": "Nubia, exchange, and empire", "children": [{"id": "8fa8a806-5490-4264-a52c-6e0ca141ba83", "type": "concept", "title": "Kerma, Kush, and Meroe"}, {"id": "cda5dc54-c4d9-421e-a0e5-820953cc7a2e", "type": "concept", "title": "Conquest, tribute, and cultural exchange"}, {"id": "b4f9873f-4f48-4c8d-a502-3e9f2ec3d5ac", "type": "concept", "title": "Pyramids, royal imagery, and local traditions"}], "description": "Students situate Egypt in African and Mediterranean networks rather than treating it as isolated."}]}, {"id": "00d600a6-7dfc-4e63-a949-6a9732e5dd31", "type": "topic", "title": "Aegean Bronze Age: Cycladic, Minoan, and Mycenaean Worlds", "description": "Aegean art introduces palace societies, maritime exchange, frescoes, ritual objects, and fortified power before classical Greece.", "children": [{"id": "69bcb84a-6688-49f7-baf9-3e05d1a9ffae", "type": "subtopic", "title": "Cycladic objects and abstraction", "children": [{"id": "e57f5dec-f7f2-4164-83c1-d8b82d200a54", "type": "concept", "title": "Marble figurines and material finish"}, {"id": "d72d461b-3d31-43d3-9b03-848d3cd372c1", "type": "concept", "title": "Burial context and collecting history"}, {"id": "ab9c727d-ee01-4763-8d0f-0aedd8181a57", "type": "concept", "title": "Modernism, abstraction, and reception"}], "description": "Students examine small-scale sculpture and the modern reception of ancient forms."}, {"id": "9f9a21dd-39db-432a-87e6-191d84f7308a", "type": "subtopic", "title": "Minoan palaces and frescoes", "children": [{"id": "3e9944d3-e484-4cb5-89be-9f2d9077f5d7", "type": "concept", "title": "Knossos and palace plans"}, {"id": "c18eedb6-ca3f-45de-a532-394dd23d90e1", "type": "concept", "title": "Fresco technique and processional imagery"}, {"id": "334a3d88-7916-4825-8abc-641f49beac25", "type": "concept", "title": "Nature, performance, and uncertain meanings"}], "description": "This subtopic connects architecture, ritual, movement, and painted imagery."}, {"id": "1eeabdb0-1083-47c9-8418-9b615de17148", "type": "subtopic", "title": "Mycenaean citadels and elite burial", "children": [{"id": "b632175f-5afd-4b9d-86ef-c4b09af72021", "type": "concept", "title": "Cyclopean masonry and palace centers"}, {"id": "a1e9dfac-4daa-4f95-a87c-4b4ee4c66408", "type": "concept", "title": "Tholos tombs and shaft graves"}, {"id": "de81aa32-8059-471f-8902-8884037587f0", "type": "concept", "title": "Gold masks, weapons, and trade goods"}], "description": "Students learn how architecture and grave goods express power and militarized hierarchy."}]}, {"id": "26d1922c-8c57-4635-915e-e22f7582b1e7", "type": "topic", "title": "Ancient Greece: Archaic and Classical Art", "description": "Greek art introduces changing ideals of body, citizenship, narrative, proportion, architecture, and public space. Students learn to compare style, function, and cultural context.", "children": [{"id": "7a7c0ba2-e5d9-4ec7-9d52-166aeedb2a19", "type": "subtopic", "title": "Archaic sculpture and vase painting", "children": [{"id": "1ec9b61d-1283-415c-ade3-54374dc6223c", "type": "concept", "title": "Kouroi and korai"}, {"id": "be59ad6e-f724-4b63-a9c5-fce2761b324b", "type": "concept", "title": "Black-figure and red-figure techniques"}, {"id": "c29cc6f9-2c9a-41a2-a666-7a73c2af3f3a", "type": "concept", "title": "Myth, symposium, athletics, and gender"}], "description": "Students track experimentation with figure, narrative, and social ritual."}, {"id": "cf662424-1646-44d0-a21c-e0f85eb513bb", "type": "subtopic", "title": "Classical sculpture and the body", "children": [{"id": "c97b3cae-16b3-44c0-b2db-a1e81d502db4", "type": "concept", "title": "Contrapposto and anatomical observation"}, {"id": "b4ce17ae-6fbc-4c8b-a641-75cf4f7396f9", "type": "concept", "title": "Polykleitos and proportion"}, {"id": "57a939cf-d7eb-45ad-ab48-1f9f5b67e034", "type": "concept", "title": "Gods, athletes, citizens, and ideals"}], "description": "This subtopic focuses on naturalism, idealization, movement, and civic value."}, {"id": "ac3300e8-a4e6-4e6a-964e-91e744660891", "type": "subtopic", "title": "Greek temples and the polis", "children": [{"id": "638f6e90-2b41-41ed-b510-ee20e1f25cbf", "type": "concept", "title": "Doric, Ionic, and Corinthian orders"}, {"id": "41cc4898-3a50-4b88-877f-985116a1f93f", "type": "concept", "title": "Acropolis planning and sculptural programs"}, {"id": "5960310a-d1ed-4a66-95e6-5f874421b81c", "type": "concept", "title": "Sanctuaries, processions, and votive offerings"}], "description": "Students connect architecture to worship, civic identity, and urban space."}]}, {"id": "e1c25b5d-d9cb-45de-bc83-ef14f4d7bc87", "type": "topic", "title": "Hellenistic and Cross-Mediterranean Worlds", "description": "The Hellenistic period expands the survey beyond the classical polis into kingdoms, cosmopolitan cities, emotional expression, and cultural hybridity.", "children": [{"id": "7bd98c36-0d1a-41ef-8d64-a4f8ea371e0e", "type": "subtopic", "title": "Empire and cosmopolitanism", "children": [{"id": "9b96d423-b2a6-439c-bfed-fc9a925d6427", "type": "concept", "title": "Alexandria, Pergamon, and royal courts"}, {"id": "65320b8c-1a9b-47f6-a90b-c5e5be4e3de0", "type": "concept", "title": "Greek, Egyptian, Persian, and local interactions"}, {"id": "49a5b516-e0a1-400f-9913-de4b08995f1c", "type": "concept", "title": "Patronage, collecting, and display"}], "description": "Students learn how Alexander's conquests and successor kingdoms changed artistic geography."}, {"id": "bf83792f-cc13-45a4-9d94-4ae3f4a1c316", "type": "subtopic", "title": "Drama, emotion, and realism", "children": [{"id": "5c50ad1b-f87f-4d84-a4ef-e031c2d8f179", "type": "concept", "title": "Pathos and theatricality"}, {"id": "5d05d489-2eb7-4da0-b13f-98f4d84c93dc", "type": "concept", "title": "Age, ethnicity, labor, and everyday life"}, {"id": "87c6d5bc-aed5-4796-aea0-05ad5c5bc20e", "type": "concept", "title": "Baroque composition and viewer engagement"}], "description": "This subtopic examines how Hellenistic art broadened the range of bodies and emotions represented."}, {"id": "a3b3286e-d592-4820-b58e-1873addd0f97", "type": "subtopic", "title": "Portable luxury and networks", "children": [{"id": "8e96cfc1-d1c3-4798-a7d6-9be2019a1ac5", "type": "concept", "title": "Coins, gems, metalwork, and glass"}, {"id": "0e027a98-409c-446e-8cba-a69a029642bc", "type": "concept", "title": "Objects across the Mediterranean and Near East"}, {"id": "d7068a90-940e-4937-8036-0ab0aed42609", "type": "concept", "title": "Mobility, imitation, and adaptation"}], "description": "Students connect art to trade, diplomacy, and elite consumption."}]}, {"id": "f2f90456-785e-45d3-af4a-c960df97ecb8", "type": "topic", "title": "Etruscan and Roman Art and Architecture", "description": "Etruscan and Roman visual culture teach students how art served family, death, empire, spectacle, urban infrastructure, and political memory.", "children": [{"id": "7dfea43b-5134-48b7-8ec5-8096b82c44bc", "type": "subtopic", "title": "Etruscan tombs and temples", "children": [{"id": "09708f90-786f-4e34-b014-1a0a6c60583f", "type": "concept", "title": "Tomb painting and funerary banquets"}, {"id": "707664bc-60f6-405f-a0d1-6c3cf5d2d536", "type": "concept", "title": "Sarcophagi and portrait conventions"}, {"id": "12b717e2-0b57-4b76-92a9-f6444b378ae0", "type": "concept", "title": "Temple form and roof sculpture"}], "description": "Students explore a distinctive Italic tradition shaped by ritual, banqueting, and terracotta sculpture."}, {"id": "3d972098-13b0-4c46-92d0-6ab6fdf5f308", "type": "subtopic", "title": "Roman portraiture and propaganda", "children": [{"id": "58059f1f-e1dc-4595-89de-5dfe4bd849c4", "type": "concept", "title": "Verism and elite identity"}, {"id": "01a4f12e-cea3-4358-bc84-9d2e81145ef1", "type": "concept", "title": "Imperial portrait types"}, {"id": "12bc3c7e-f68f-43bf-a78e-337bcd3b0276", "type": "concept", "title": "Triumphal arches, columns, coins, and state reliefs"}], "description": "This subtopic shows how identity and authority were crafted through images."}, {"id": "16da9caf-69be-4f8b-9c41-3ab804e27148", "type": "subtopic", "title": "Roman architecture and urban life", "children": [{"id": "0fdeb117-6955-48fa-b7de-72cede4e0422", "type": "concept", "title": "Aqueducts, roads, baths, amphitheaters, and basilicas"}, {"id": "3723adcc-af27-45ea-b69c-3da6dfacfede", "type": "concept", "title": "Concrete, vaulting, and domes"}, {"id": "3f080576-9126-4db1-881a-4b440d93ec80", "type": "concept", "title": "Domestic space, wall painting, and Pompeii"}], "description": "Students learn how concrete, engineering, and planning transformed space and society."}]}, {"id": "5ab58347-9aae-4760-8538-0b7c3f15095e", "type": "topic", "title": "Late Antiquity and Early Christian Art", "description": "Late Antique art reveals religious transformation, imperial change, and new image functions. Students learn how classical forms were adapted for Christian, Jewish, and imperial contexts.", "children": [{"id": "2f0093ef-2aa9-4dda-a110-8b1f1340b183", "type": "subtopic", "title": "Catacombs and early Christian imagery", "children": [{"id": "721c894b-ec2b-437e-ae9f-ad69b94c22ce", "type": "concept", "title": "Good Shepherd, Jonah, orant figures, and symbols"}, {"id": "248ede64-9c6b-48ef-8613-9c96b8490942", "type": "concept", "title": "Burial, martyrdom, and community identity"}, {"id": "7cb6af80-855c-4a00-a42e-04586e514328", "type": "concept", "title": "House churches and early worship spaces"}], "description": "Students examine symbolic imagery made before and after Christianity's legalization."}, {"id": "ea202d8b-59d4-47ce-ab92-ead49c6539d1", "type": "subtopic", "title": "Basilicas, mosaics, and sacred space", "children": [{"id": "6c845de1-fa72-456b-8aa6-d03abc2ae3cc", "type": "concept", "title": "Basilica plan and processional movement"}, {"id": "a0f4add1-3991-4919-84aa-628d4fcdbcb4", "type": "concept", "title": "Apse mosaics and visual hierarchy"}, {"id": "59d0f547-2703-480e-8c20-c78fd669bc1e", "type": "concept", "title": "Rome, Ravenna, and imperial Christianity"}], "description": "This subtopic connects architecture to liturgy and imperial patronage."}, {"id": "2041e9d7-6941-4311-ba71-bf58c75da6b1", "type": "subtopic", "title": "Jewish and late antique visual culture", "children": [{"id": "9028da92-1496-466e-806e-79ff6619b45e", "type": "concept", "title": "Synagogue mosaics and scriptural imagery"}, {"id": "26035093-5274-41df-9473-c00479a64546", "type": "concept", "title": "Shared motifs across communities"}, {"id": "df059605-c055-480f-a482-b473b80d6633", "type": "concept", "title": "Continuity and transformation of classical forms"}], "description": "Students broaden the period beyond Christian narratives alone."}]}, {"id": "7d6ea7c4-ce68-47a3-84d1-43a04258ddea", "type": "topic", "title": "Byzantine Art and Empire", "description": "Byzantine art teaches students to analyze icons, mosaics, manuscripts, luxury objects, sacred architecture, and the politics of images across a long-lived empire.", "children": [{"id": "450a56f3-e89e-4ec5-b105-f40a8ea52650", "type": "subtopic", "title": "Icons and image debates", "children": [{"id": "fcf06f06-5398-404c-a79c-e39fdd4abdfe", "type": "concept", "title": "Icon, relic, and devotion"}, {"id": "51bcbc6b-8460-45aa-bda4-8f42d5c9b81a", "type": "concept", "title": "Iconoclasm and iconophile arguments"}, {"id": "e69bfefe-6ebb-4964-8c3e-bbdcd65fd1a0", "type": "concept", "title": "Image, presence, and authority"}], "description": "Students learn why images could become central to theology, devotion, and political conflict."}, {"id": "7c67991d-527e-4852-b4e4-e8ca671fb8d6", "type": "subtopic", "title": "Hagia Sophia and sacred architecture", "children": [{"id": "17d96ad3-03e8-4c12-ac5a-f7033595c108", "type": "concept", "title": "Dome, pendentives, and spatial drama"}, {"id": "a2836077-8335-4368-a227-d421a6087513", "type": "concept", "title": "Mosaic, marble, and light"}, {"id": "b05e678b-1728-4500-a5f8-ecd2befc1d9d", "type": "concept", "title": "Liturgy, procession, and imperial patronage"}], "description": "This subtopic connects engineering, light, ritual, and imperial ideology."}, {"id": "a0335621-b649-4c65-beef-8298cd07bf77", "type": "subtopic", "title": "Byzantine manuscripts and luxury arts", "children": [{"id": "b7ba39b1-f42a-4268-9eaf-5eb33cf2459b", "type": "concept", "title": "Illuminated manuscripts and ivories"}, {"id": "c9ff2a68-21ce-488f-b5ea-f18a2b305b26", "type": "concept", "title": "Enamels, metalwork, and textiles"}, {"id": "63b1120d-e578-466b-a0d9-61a0f1a0d90c", "type": "concept", "title": "Cross-cultural exchange with Islam and the West"}], "description": "Students examine portable objects as vehicles of devotion, diplomacy, and prestige."}]}, {"id": "2f1a7d72-12d3-4cfe-881c-fccc3c55e2b5", "type": "topic", "title": "Early Islamic Art and Architecture", "description": "Early Islamic art introduces students to mosque architecture, calligraphy, ornament, luxury objects, and empire across the Umayyad and Abbasid worlds.", "children": [{"id": "f356c744-edd9-4890-bf74-d1fca4e311c6", "type": "subtopic", "title": "Mosque architecture and sacred space", "children": [{"id": "76bec783-6809-4877-96e0-bbbe39fcf903", "type": "concept", "title": "Qibla, mihrab, minbar, courtyard, and hypostyle hall"}, {"id": "6a9943ee-62a2-4cac-a7f1-bf160d3d0ecd", "type": "concept", "title": "Dome of the Rock and Great Mosque of Damascus"}, {"id": "00b1a152-8763-44b0-8170-1bf2a73d5785", "type": "concept", "title": "Prayer, community, and urban setting"}], "description": "Students learn core architectural forms and their ritual functions."}, {"id": "582a32c5-6d1d-4362-99b4-3ebf74ccd27e", "type": "subtopic", "title": "Calligraphy, ornament, and aniconism", "children": [{"id": "61eee23c-eaae-47bb-8677-27a431f1c2ea", "type": "concept", "title": "Arabic script and Qur'anic inscription"}, {"id": "be443056-816e-4ac5-ae35-7dff110ea0c1", "type": "concept", "title": "Geometry, vegetal ornament, and arabesque"}, {"id": "a03641be-65a9-41fc-b270-230b3241f9a6", "type": "concept", "title": "Debates about figuration and context"}], "description": "This subtopic explores how script and pattern carried meaning and beauty."}, {"id": "208c88c0-c43a-414f-aee6-e134a3950598", "type": "subtopic", "title": "Luxury arts and global exchange", "children": [{"id": "e909fd04-5955-4616-ab1e-9356dfe08e48", "type": "concept", "title": "Ceramics, glass, metalwork, and textiles"}, {"id": "c6016b62-53bf-4835-8f78-120ccc273c04", "type": "concept", "title": "Paper, books, and knowledge networks"}, {"id": "7837d125-29b6-4710-a48c-89ceea331802", "type": "concept", "title": "Mediterranean, Central Asian, African, and Indian Ocean connections"}], "description": "Students connect Islamic art to trade, science, court culture, and technology."}]}, {"id": "671633b6-3774-483c-b7c7-ec8f3b632dc6", "type": "topic", "title": "Medieval Islamic, Iberian, and Mediterranean Exchange", "description": "This topic emphasizes contact zones rather than isolated civilizations. Students study objects, buildings, and manuscripts shaped by trade, translation, conquest, coexistence, and rivalry.", "children": [{"id": "d37bd57c-95d5-449d-96f7-f543ee3eb2bf", "type": "subtopic", "title": "Al-Andalus and hybrid forms", "children": [{"id": "d767c878-d9bd-4763-b43f-98f8e0557644", "type": "concept", "title": "Great Mosque of Cordoba"}, {"id": "e38eccdf-f7cc-47c1-ba6a-251aebc699c1", "type": "concept", "title": "Horseshoe arches, muqarnas, and tilework"}, {"id": "11eda7db-7feb-4421-9f4a-037c789b0384", "type": "concept", "title": "Court culture, conquest, and reuse"}], "description": "Students explore Iberia as a site of Islamic, Christian, and Jewish artistic interaction."}, {"id": "b529ebe8-3871-447f-afba-0a605993cf8a", "type": "subtopic", "title": "Crusader and Mediterranean encounters", "children": [{"id": "4a79e867-ca63-411b-9610-c0cdfaa0e94b", "type": "concept", "title": "Pilgrimage, relics, and portable objects"}, {"id": "5c5cea3f-0f81-42a4-a545-7d5eff4a06e6", "type": "concept", "title": "Venice, Byzantium, and the Levant"}, {"id": "c049e3fa-492b-4bc3-a3e0-bf03e227aba1", "type": "concept", "title": "Appropriation, translation, and spolia"}], "description": "This subtopic examines how conflict and contact shaped visual exchange."}, {"id": "f0e6d6d4-d2b3-4cae-aa6d-2943a2b303cd", "type": "subtopic", "title": "Trade networks and material movement", "children": [{"id": "d4e34ff6-42f3-4d13-97d2-3164b154dff6", "type": "concept", "title": "Ivory, silk, glass, pigments, and metalwork"}, {"id": "dd9daa67-fd06-487c-8a08-3204775ca88a", "type": "concept", "title": "Ports, merchants, and diplomatic gifts"}, {"id": "be1cc372-13da-458a-875c-89234479cc4a", "type": "concept", "title": "Object biographies across regions"}], "description": "Students see materials as evidence of connected worlds."}]}, {"id": "e71b4fe8-bfde-47ac-87b5-8b41a09e5dfe", "type": "topic", "title": "Early Medieval Europe: Migration, Monasticism, and Insular Art", "description": "Early medieval art shows how new kingdoms, monastic communities, books, metalwork, and portable prestige objects shaped visual culture after Rome.", "children": [{"id": "f9fe8d81-eb39-42eb-87a1-1fdce7212bbe", "type": "subtopic", "title": "Migration-period metalwork", "children": [{"id": "71176ace-6b13-4806-b51b-90ba26fd2fe9", "type": "concept", "title": "Fibulae, belt fittings, weapons, and cloisonne"}, {"id": "7520f800-60f1-47c8-83fb-42131e8a0ecf", "type": "concept", "title": "Animal style and abstraction"}, {"id": "7dbb3302-c7c6-4251-bb6c-59ab5fd5f137", "type": "concept", "title": "Burial goods and elite display"}], "description": "Students learn how portable luxury objects expressed identity and status."}, {"id": "cd6fbbd5-2714-4107-abfd-184237ecfd0b", "type": "subtopic", "title": "Insular manuscripts", "children": [{"id": "52a793d3-1082-4f1c-8767-5bf227b3ee7d", "type": "concept", "title": "Carpet pages and decorated initials"}, {"id": "2fb3f254-8d0b-4b1f-a022-2f2bec73ae5f", "type": "concept", "title": "Interlace, zoomorphic forms, and script"}, {"id": "f25b9107-4abb-45ce-b80f-843a977aaecb", "type": "concept", "title": "Book of Kells and Lindisfarne Gospels"}], "description": "This subtopic examines books as sacred objects, intellectual labor, and visual invention."}, {"id": "39eda0a9-5e5f-49e0-8c7d-f5e3dba6231f", "type": "subtopic", "title": "Carolingian and Ottonian renewal", "children": [{"id": "545d1ccf-d4ed-40c9-b8aa-abcd7ebeb475", "type": "concept", "title": "Court schools and manuscript reform"}, {"id": "29cc63b3-0040-40d4-a38a-52d9098b6100", "type": "concept", "title": "Palace chapels and imperial imagery"}, {"id": "7b446db7-41b4-45af-9e6a-d4ea4c5e164d", "type": "concept", "title": "Ivories, metalwork, and reliquaries"}], "description": "Students analyze how rulers used art to claim continuity with Rome and Christianity."}]}, {"id": "2022c8f1-e6f5-4d90-8853-3ac8026f46eb", "type": "topic", "title": "Romanesque Art and Architecture", "description": "Romanesque art connects pilgrimage, monastic reform, sculpture, relics, and monumental church building across medieval Europe.", "children": [{"id": "dbc494f0-fa5d-4b22-a21e-4fb473301695", "type": "subtopic", "title": "Pilgrimage and church planning", "children": [{"id": "514cfbdd-87f4-4e42-93b6-fea1414672b9", "type": "concept", "title": "Ambulatories, radiating chapels, and transepts"}, {"id": "add6eac6-bc0d-4f9a-a1a9-c12e68528003", "type": "concept", "title": "Pilgrimage roads and sacred geography"}, {"id": "e09a170c-9b11-48c3-a0b2-8749615bcf7e", "type": "concept", "title": "Relics, cults, and church economies"}], "description": "Students learn how movement, relics, and crowds shaped architectural form."}, {"id": "7b64f143-8d7d-4cdb-9ba0-462593695184", "type": "subtopic", "title": "Portal sculpture and narrative programs", "children": [{"id": "ede88e0d-7cc2-4bee-9bf2-7bf709eacfb3", "type": "concept", "title": "Tympanum, lintel, jamb, and trumeau"}, {"id": "74289a56-d29e-4409-b053-142cdc3b771c", "type": "concept", "title": "Last Judgment imagery"}, {"id": "92fb79ce-34d6-4a93-8e99-d58cc6cf8ada", "type": "concept", "title": "Monsters, margins, and moral instruction"}], "description": "This subtopic shows how architecture became a public teaching surface."}, {"id": "63d25a27-08ff-4b72-9c2c-3fa6cd0c399d", "type": "subtopic", "title": "Monastic reform and material culture", "children": [{"id": "e0180265-9552-458b-8ebe-6592845a2be1", "type": "concept", "title": "Cluny and Cistercian ideals"}, {"id": "618b05a5-b243-4c10-871a-77ab9ca675ac", "type": "concept", "title": "Reliquaries, crosses, and liturgical objects"}, {"id": "0de1c2ac-72f5-4576-a39d-10c44451ad43", "type": "concept", "title": "Manuscripts, cloisters, and learning"}], "description": "Students connect art to religious communities, patronage, and devotional objects."}]}, {"id": "3ca51a66-a782-4ba6-b037-fc18dc81de94", "type": "topic", "title": "Gothic Art and Architecture", "description": "Gothic art teaches students how architecture, glass, sculpture, urban life, and theology could merge into immersive visual systems.", "children": [{"id": "32b41f58-2b66-4270-8820-d42c8ba4df6c", "type": "subtopic", "title": "Gothic structural systems", "children": [{"id": "d17cf934-30b9-4e90-9840-3f1afabe5567", "type": "concept", "title": "Pointed arch, rib vault, and flying buttress"}, {"id": "f4ce0aeb-0d5d-4c7d-8d6b-861c828e4a6d", "type": "concept", "title": "Choir, nave, transept, and facade"}, {"id": "41e428f9-7800-412c-b682-88afa1f1197e", "type": "concept", "title": "Engineering, craft, and risk"}], "description": "Students learn the architectural logic behind height, light, and spatial drama."}, {"id": "d051a1be-39e7-4f32-bc75-c39e462d17e7", "type": "subtopic", "title": "Stained glass and sculptural programs", "children": [{"id": "cca15cf4-ea84-4912-942e-a52876a3c54f", "type": "concept", "title": "Rose windows and lancets"}, {"id": "001894e4-8f97-4b45-9250-fd3b94df5f18", "type": "concept", "title": "Prophets, kings, saints, and portals"}, {"id": "c3f0a51c-e42a-4152-a934-e96daf2cd16b", "type": "concept", "title": "Typology, narrative cycles, and donors"}], "description": "This subtopic connects image, light, narrative, and devotion."}, {"id": "c176ccae-71a6-4027-8162-3cb7fc2cd3c3", "type": "subtopic", "title": "Urban cathedrals and social worlds", "children": [{"id": "918fda60-1ca6-4ad6-b199-2f50947946cb", "type": "concept", "title": "Guilds, bishops, monarchs, and towns"}, {"id": "b2107485-a962-41c1-92c6-30961e4423d5", "type": "concept", "title": "Pilgrimage, relics, and festivals"}, {"id": "70aa29cd-43e0-4c75-b099-7fed325c4d6b", "type": "concept", "title": "Labor, craft organization, and construction time"}], "description": "Students examine Gothic buildings as civic, economic, and spiritual projects."}]}, {"id": "3e8d0527-6910-42f3-b6c7-6c3be01369e3", "type": "topic", "title": "Manuscripts, Books, Luxury Arts, and Material Culture", "description": "This topic slows down on objects often treated as secondary to monuments. Students learn how books, textiles, metalwork, ceramics, and small-scale objects carry complex histories.", "children": [{"id": "4360ebd5-10e7-45b5-aaf1-6075ebd4f5b0", "type": "subtopic", "title": "Manuscript production", "children": [{"id": "652ed5d2-ac31-4cf8-a8f7-ca177e1559e6", "type": "concept", "title": "Parchment, paper, pigments, gold, and binding"}, {"id": "b90470f2-7cca-4126-b9d1-c7ca43cc5883", "type": "concept", "title": "Scriptoria, patrons, scribes, and illuminators"}, {"id": "bcc6810c-9671-4db6-b8b2-ed1b84ce7584", "type": "concept", "title": "Text-image relationships and marginalia"}], "description": "Students learn the labor and materials behind medieval books."}, {"id": "cfab7859-f873-4a6b-b47d-bd2e2f4b6742", "type": "subtopic", "title": "Luxury materials and craft", "children": [{"id": "da355952-6b30-46f2-bcb8-deab891733ca", "type": "concept", "title": "Ivory, enamel, gems, glass, and metalwork"}, {"id": "87f5a0c6-a944-4b2e-9b72-9544ec2673e9", "type": "concept", "title": "Textiles, embroidery, and clothing"}, {"id": "0a2525e8-cb3d-49ed-926d-f4c39441739b", "type": "concept", "title": "Technique, touch, and sensory experience"}], "description": "This subtopic examines value, technique, and meaning in elite and devotional objects."}, {"id": "0cdb61ce-a24e-4818-8015-3acc8d1b455e", "type": "subtopic", "title": "Object biographies", "children": [{"id": "98ad8116-bc5f-4adb-a443-2f55b89605d7", "type": "concept", "title": "Original use and later reuse"}, {"id": "ab240ba4-d125-4c64-80f6-7cca1168b5e2", "type": "concept", "title": "Gifts, loot, trade, and inheritance"}, {"id": "b1a565e7-bd04-482e-8732-b4b2e721d1d8", "type": "concept", "title": "Conservation, restoration, and museum interpretation"}], "description": "Students trace objects through production, use, movement, collection, and display."}]}, {"id": "9d9fabd6-7107-43a2-897b-935d0d0f0b07", "type": "topic", "title": "Global Ancient and Medieval Traditions Beyond the Standard Western Survey", "description": "A survey must not let 'ancient to medieval' mean only the Mediterranean and Europe. This topic adds comparative global traditions and asks students to think carefully across regions.", "children": [{"id": "ac711de1-63f8-481f-8fef-3d7145ae3f7f", "type": "subtopic", "title": "Africa beyond Egypt", "children": [{"id": "a4bf8edd-1a61-4601-a6e0-15c63ea029fa", "type": "concept", "title": "Nok, Djenne, Aksum, and Great Zimbabwe"}, {"id": "ca543386-ba58-45e6-9f6c-673c2fab58ae", "type": "concept", "title": "Terracotta, metalwork, architecture, and trade"}, {"id": "1c5a7088-9367-46bc-8959-247cb75d7a9a", "type": "concept", "title": "Sahara, Nile, Red Sea, and Indian Ocean networks"}], "description": "Students examine African visual cultures as major centers of artistic innovation."}, {"id": "bcb51d05-51ec-4d77-96ee-9ef292c4806e", "type": "subtopic", "title": "South, East, and Southeast Asia", "children": [{"id": "684ebf09-e8be-4b55-beb2-ef5fa0ab4cab", "type": "concept", "title": "Stupas, temples, sculpture, and pilgrimage"}, {"id": "c3cc64e0-1e49-45c7-9f01-31163ced8ac3", "type": "concept", "title": "China, Korea, Japan, India, and Southeast Asia"}, {"id": "b1ed259e-51a3-4a28-9aa9-8d616df78d3b", "type": "concept", "title": "Silk Road exchange and manuscript cultures"}], "description": "This subtopic introduces Buddhist, Hindu, courtly, and religious visual systems across Asia."}, {"id": "28229a52-f8b6-472c-86a9-8979899c628f", "type": "subtopic", "title": "Ancient Americas and Oceania", "children": [{"id": "4dd9d061-dfb4-461e-aad0-e96f35642711", "type": "concept", "title": "Olmec, Maya, Teotihuacan, Moche, Nazca, and Andean traditions"}, {"id": "c0704bbb-614d-48c4-a17f-f3f8dfa3270d", "type": "concept", "title": "Monumentality, calendar, ritual, and rulership"}, {"id": "e6c1966f-ee9f-4405-949a-6794e8470d52", "type": "concept", "title": "Pacific navigation, carving, textile, and sacred space"}], "description": "Students encounter major visual systems outside Eurasian chronologies."}]}, {"id": "51075d89-02ac-47d0-aa68-f07d9da27b22", "type": "topic", "title": "Museums, Cultural Heritage, Provenance, and Final Object Study Portfolio", "description": "The course ends by asking students to use art-historical methods responsibly. Students synthesize visual analysis, context, comparison, provenance, and ethics in a polished object-study portfolio.", "children": [{"id": "a2def6eb-a975-4e57-96d0-7b419ffcc5bf", "type": "subtopic", "title": "Museum display and interpretation", "children": [{"id": "73fc8fd5-a9a0-48f9-b425-d919df05d5cc", "type": "concept", "title": "Gallery narratives and display choices"}, {"id": "13eb8cef-bde1-4945-a266-ed027f79e0d7", "type": "concept", "title": "Digital collections and image access"}, {"id": "516ed6a9-a527-423b-a0ca-3f1dd323abfb", "type": "concept", "title": "Audience, accessibility, and public education"}], "description": "Students learn how labels, lighting, grouping, and institutional history shape meaning."}, {"id": "2ef04d7d-0829-4cf3-9dee-8fd69b6e3be6", "type": "subtopic", "title": "Provenance and cultural heritage ethics", "children": [{"id": "14e3ab04-6400-44ec-8856-4bf051c9dedc", "type": "concept", "title": "Archaeological context and illicit trade"}, {"id": "9e2bad27-6596-4537-91b3-2c09a249de04", "type": "concept", "title": "Colonial collecting and repatriation debates"}, {"id": "d0a64f67-e61e-400a-86b1-2d053455bfbd", "type": "concept", "title": "Cultural property law and ethical stewardship"}], "description": "This subtopic introduces questions of ownership, excavation, collecting, restitution, and care."}, {"id": "b97a1a34-953a-405c-ab91-2f700c7c741a", "type": "subtopic", "title": "Final object study portfolio", "children": [{"id": "944e6cc4-3d3f-4550-ad38-519cfb2198d8", "type": "concept", "title": "Object description and visual evidence"}, {"id": "fe0a3efd-cce9-4092-9e0e-fc309a9d6b2c", "type": "concept", "title": "Historical context and comparison set"}, {"id": "019446c7-b5dc-449f-9839-f758831d633a", "type": "concept", "title": "Bibliography, image captions, and reflection"}], "description": "Students bring together close looking, research, comparison, and clear writing."}]}], "dbBacked": true}$ah1json$::jsonb,
